package jobs
type Job struct { Name string; NightOnly bool }
var catalog = []Job{
    {"water-level", false},
    {"gate-health", false},
    {"radio-sync", false},
    {"silt-scan", true},
    {"lamp-check", true},
}
func Enabled(night bool) []Job {
    result := []Job{}
    for _, job := range catalog {
        if !job.NightOnly || night { result = append(result, job) }
    }
    return result
}
